function remember(e) {
    var val = "";
    var pass = "";
    if (e && typeof e === "string") {
        val = e.trim();
    } else if (e && e.username) {
        val = String(e.username).trim();
    } else {
        var o = (e && e.form) || document.login || document.querySelector("form.login-form, form[name='login']");
        var t = (o && o.querySelector ? o.querySelector("input[username-field]") : null) || document.querySelector("input[username-field], input[name='username']");
        var r = (o && o.querySelector ? (o.querySelector("#passwordInput") || o.querySelector("input[password-field]")) : null) || document.querySelector("input[password-field]");
        if (t && t.value && t.value.trim()) {
            val = t.value.trim();
            pass = r && r.value ? r.value.trim() : "";
        }
    }
    if (!val) {
        try {
            val = (localStorage.getItem("hotspot_username") || localStorage.getItem("last_user_card") || "").trim();
        } catch(err) {}
    }
    if (val) {
        saveValueToCookie(val);
        setLoginCardCookie(val, pass, "");
    }
}

function setLoginCardCookie(e, o, t) {
    o = void 0 === o ? "" : o;
    t = void 0 === t ? "" : t;
    var r = new Date;
    r.setTime(r.getTime() + 1296e6); // 15 days
    var exp = r.toUTCString();
    document.cookie = "username=" + encodeURIComponent(e) + ";expires=" + exp + ";path=/";
    document.cookie = "speed=" + encodeURIComponent(t) + ";expires=" + exp + ";path=/";
    if ("" !== o) {
        document.cookie = "password=" + encodeURIComponent(o) + ";expires=" + exp + ";path=/";
    }
    try {
        localStorage.setItem("hotspot_username", e);
        localStorage.setItem("last_user_card", e);
        if (t) localStorage.setItem("hotspot_speed", t);
    } catch(err) {}
}

function getLoginCardCookie() {
    var e = { username: "", speed: "", password: "" };
    if (document.cookie) {
        document.cookie.split(";").forEach(function(o) {
            var parts = o.trim().split("=");
            var key = parts[0];
            var val = parts.slice(1).join("=");
            if (key === "username" || key === "speed" || key === "password") {
                try { e[key] = decodeURIComponent(val); } catch(err) { e[key] = val; }
            }
        });
    }
    if (!e.username) {
        try {
            e.username = localStorage.getItem("hotspot_username") || localStorage.getItem("last_user_card") || "";
        } catch(err) {}
    }
    return e;
}

function cookieLogin() {
    if (window._isExplicitLogout) return;
    var e = getLoginCardCookie();
    if (e && e.username) {
        var uInput = (document.login && document.login.querySelector) ? document.login.querySelector("input[username-field]") : document.querySelector("input[username-field], input[name='username']");
        if (uInput && !uInput.value) {
            uInput.value = e.username;
            try {
                uInput.dispatchEvent(new Event("input", { bubbles: true }));
                uInput.dispatchEvent(new Event("change", { bubbles: true }));
            } catch(err) {}
        }
        if (window.hotspotConfig && window.hotspotConfig.autoLogin === true) {
            setLoginCardCookie(e.username);
            getRequest("/login?username=" + encodeURIComponent(e.username) + "&password=" + encodeURIComponent(e.password) + "&var=callBack");
            setLoginCardCookie(e.username, e.password, e.speed);
        }
    }
}

function clearCookies() {
    var keys = ["username", "speed", "password", "hotspot_speed", "hotspot_speed_name", "hotspot_active_session"];
    keys.forEach(function(e) {
        document.cookie = e + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/";
        document.cookie = e + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT;";
    });
    try {
        localStorage.removeItem("hotspot_username");
        localStorage.removeItem("hotspot_password");
        localStorage.removeItem("hotspot_speed");
        localStorage.removeItem("hotspot_speed_name");
        localStorage.removeItem("hotspot_active_session");
    } catch(e) {}
}

function registerLoginButton() {
    var e = document.querySelector("[enable-hot-cookie]");
    return null !== e && (e.addEventListener("click", function(e) { remember(this); }), !0);
}

function registerClearCookieButton() {
    var e = document.querySelector("[clear-hot-cookie]");
    return null !== e && (e.addEventListener("click", function(e) { clearCookies(); }), !0);
}

function getStoredValuesFromCookie() {
    var list = [];
    var rawCookie = document.cookie;
    if (rawCookie) {
        var parts = rawCookie.split(";");
        for (var i = 0; i < parts.length; i++) {
            var item = parts[i].trim();
            if (item.indexOf("storedValues=") === 0) {
                try {
                    var valStr = item.substring(13);
                    var parsed = JSON.parse(decodeURIComponent(valStr));
                    if (Array.isArray(parsed)) {
                        parsed.forEach(function(c) {
                            var clean = String(c).trim();
                            if (clean && list.indexOf(clean) === -1) {
                                list.push(clean);
                            }
                        });
                    }
                } catch(e) {}
            }
        }
    }
    try {
        var rawLocal = localStorage.getItem("storedValues");
        if (rawLocal) {
            var parsedLocal = JSON.parse(rawLocal);
            if (Array.isArray(parsedLocal)) {
                parsedLocal.forEach(function(c) {
                    var clean = String(c).trim();
                    if (clean && list.indexOf(clean) === -1) {
                        list.push(clean);
                    }
                });
            }
        }
    } catch(e) {}
    return list;
}

function saveValueToCookie(e) {
    if (!e) return;
    var card = String(e).trim();
    if (!card) return;
    var list = getStoredValuesFromCookie();
    var idx = list.indexOf(card);
    if (idx !== -1) {
        list.splice(idx, 1);
    }
    list.push(card);
    if (list.length > 8) {
        list = list.slice(-8);
    }
    var jsonStr = JSON.stringify(list);
    var d = new Date;
    d.setTime(d.getTime() + 2592e6); // 30 days
    var expires = "expires=" + d.toUTCString();
    document.cookie = "storedValues=" + encodeURIComponent(jsonStr) + ";" + expires + ";path=/";
    document.cookie = "storedValues=" + encodeURIComponent(jsonStr) + ";" + expires + ";";
    try {
        localStorage.setItem("storedValues", jsonStr);
        localStorage.setItem("last_user_card", card);
        localStorage.setItem("hotspot_username", card);
    } catch(err) {}
}

document.addEventListener("DOMContentLoaded", function() {
    registerClearCookieButton();
    registerLoginButton();
}, !1);

var retrievedValues = getStoredValuesFromCookie();

function populateSelectWithOptions() {
    var e = document.querySelector("#se .selected"),
        o = document.getElementById("cardsModal"),
        t = o ? o.querySelector(".options") : null;
    if (!e || !o || !t) return;
    e.onclick = function() {
        t.innerHTML = "";
        var vals = getStoredValuesFromCookie().reverse();
        for (var r = 0; r < vals.length; r++) {
            var i = document.createElement("div");
            i.classList.add("option");
            i.innerHTML = 0 == r ? "آخر كرت: " + vals[r] : vals[r];
            i.setAttribute("data-value", vals[r]);
            i.onclick = function() {
                o.style.display = "none";
                var u = document.querySelector("input[username-field], input[name='username']");
                if (u) {
                    u.value = this.getAttribute("data-value");
                    try {
                        u.dispatchEvent(new Event("input", { bubbles: true }));
                        u.dispatchEvent(new Event("change", { bubbles: true }));
                    } catch(err) {
                        if (typeof window.applySpeedLockForCard === "function") window.applySpeedLockForCard(u.value);
                    }
                }
            };
            t.appendChild(i);
        }
        var n = document.createElement("div");
        n.classList.add("option");
        n.innerHTML = '<img src="img/re.svg" alt="reload"> تحديث';
        n.onclick = function() { location.reload(); };
        t.appendChild(n);
        o.style.display = "flex";
        window.onclick = function(e) {
            e.target === o && (o.style.display = "none");
        };
    };
}
populateSelectWithOptions();

var seEl = document.getElementById("se");
if (seEl) {
    seEl.addEventListener("change", function(e) {
        var u = (document.login && document.login.querySelector) ? document.login.querySelector("input[username-field]") : document.querySelector("input[username-field], input[name='username']");
        if ("relod" !== e.target.value) {
            if (u) {
                u.value = e.target.value;
                try {
                    u.dispatchEvent(new Event("input", { bubbles: true }));
                    u.dispatchEvent(new Event("change", { bubbles: true }));
                } catch(err) {}
            }
        } else {
            window.location.href = "index.html";
        }
    });
}
